import * as THREE from 'three';
import {heartPart} from './thorax-data.js';
// Educational motion. All transforms are recomputed from rest; no accumulated drift.
export function organMotionKind(r){const n=r.name.toLowerCase();if(r.layer==='skeleton'&&/rib\.[lr]\.\d+$|sternum/.test(n))return'chest';if(r.layer==='cardiovascular'&&/leaflet|^(aortic|pulmonary|mitral|tricuspid) valve\./.test(n))return'valve';if(n==='diaphragm.001')return'diaphragm';if(r.layer==='cardiovascular'&&/^(right atrium|left atrium|cardiac atrium)\./.test(n))return'atrial';if(r.layer==='cardiovascular'&&/heart|cardiac atrium|ventricle|atrium|papillary|myocard|interventricular/.test(n)&&!/vein|arter|aort/.test(n))return 'heart';if(r.layer==='visceral'&&(/bronchopulmonary segment/.test(n)||/lung|pulmonary lobe/.test(n)&&!/bronch|hilus|ligament/.test(n)))return 'lung';return null;}
export function motionFactors(kind,t,bpm=72,rpm=14){if(kind==='heart'||kind==='atrial'){const phase=(t*bpm/60)%1;const pulse=kind==='atrial'?Math.exp(-Math.pow((phase-.075)/.055,2)):Math.max(0,Math.sin(Math.PI*Math.max(0,Math.min(1,(phase-.14)/.48))));return new THREE.Vector3(1-.045*pulse,1-.025*pulse,1-.04*pulse);}if(kind==='diaphragm'||kind==='chest'||kind==='valve')return new THREE.Vector3(1,1,1);const breath=(1-Math.cos(t*rpm/60*Math.PI*2))/2;return new THREE.Vector3(1+.025*breath,1+.018*breath,1+.04*breath);}

export class OrganMotion{
 constructor(){this.groups=[];this.enabled=false;this.bpm=72;this.rpm=14;this.time=0;this.last=null;}
 rebuild(objects,sex){this.restore();const groups=new Map();for(const o of objects.values()){if((o.userData.record.sex||'male')!==sex)continue;const kind=organMotionKind(o.userData.record);if(!kind)continue;const key=kind==='valve'?'valve-'+heartPart(o.userData.record):kind==='chest'?'chest-'+o.userData.record.id:kind==='lung'?'lung'+(o.userData.worldCenter.x>0?'l':'r'):kind;if(!groups.has(key))groups.set(key,{kind,items:[],box:new THREE.Box3()});const g=groups.get(key);g.items.push(o);g.box.expandByObject(o);o.userData.restScale??=o.scale.clone();o.userData.restQuaternion??=o.quaternion.clone();}this.groups=[...groups.values()].map(g=>({...g,center:g.box.getCenter(new THREE.Vector3())}));for(const g of this.groups)if(g.kind==='valve')for(const o of g.items){const a=o.geometry.attributes.position;o.userData.valveRest??=a.array.slice();const center=o.worldToLocal(g.center.clone());let radius=0;for(let i=0;i<a.count;i++)radius=Math.max(radius,new THREE.Vector3().fromBufferAttribute(a,i).distanceTo(center));o.userData.valveCenter=center;o.userData.valveRadius=radius;}}
 restore(){if(!this.dirty){this.last=null;return;}this.dirty=false;for(const g of this.groups)for(const o of g.items){o.position.copy(o.userData.basePosition);o.scale.copy(o.userData.restScale);o.quaternion.copy(o.userData.restQuaternion);if(o.userData.valveRest){o.geometry.attributes.position.array.set(o.userData.valveRest);o.geometry.attributes.position.needsUpdate=true;o.geometry.computeVertexNormals();o.geometry.computeBoundingSphere();}}this.last=null;}
 tick(ms,allowed){if(!this.enabled||!allowed){this.restore();return false;}if(this.last!==null)this.time+=Math.min(.05,(ms-this.last)/1000);this.last=ms;let any=false;for(const g of this.groups){const s=motionFactors(g.kind,this.time,this.bpm,this.rpm);for(const o of g.items){if(!o.visible)continue;any=true;this.dirty=true;const pivot=o.parent.worldToLocal(g.center.clone());o.position.copy(o.userData.basePosition).sub(pivot).multiply(s).add(pivot);o.scale.copy(o.userData.restScale).multiply(s);if(g.kind==='valve'){deformValve(o,cardiacOpening(heartPart(o.userData.record),this.time*this.bpm/60));}if(g.kind==='chest'){const breath=(1-Math.cos(this.time*this.rpm/60*Math.PI*2))/2,n=o.userData.record.name.toLowerCase();if(/rib/.test(n)){const hinge=new THREE.Vector3(g.center.x,g.center.y,g.box.min.z);const localHinge=o.parent.worldToLocal(hinge.clone()),rotation=new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1,0,0),-.022*breath);o.position.copy(o.userData.basePosition).sub(localHinge).applyQuaternion(rotation).add(localHinge);o.quaternion.copy(rotation).multiply(o.userData.restQuaternion);}else{o.position.y+=.002*breath;o.position.z+=.003*breath;}}if(g.kind==='diaphragm'){const worldOffset=new THREE.Vector3(0,-.008*(1-Math.cos(this.time*this.rpm/60*Math.PI*2))/2,0);const localOffset=o.parent.worldToLocal(worldOffset.add(g.center.clone())).sub(o.parent.worldToLocal(g.center.clone()));o.position.add(localOffset);}}}return any;}
}

export function cardiacOpening(key,cycle){const phase=((cycle%1)+1)%1;const ease=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x);};const sl=ease((phase-.23)/.04)*(1-ease((phase-.49)/.04));return ['mitral','tricuspid'].includes(key)?(phase<.14?1-ease((phase-.1)/.04):ease((phase-.68)/.04)):sl;}
export function deformValve(o,open){const a=o.geometry.attributes.position,rest=o.userData.valveRest,c=o.userData.valveCenter,R=o.userData.valveRadius;if(!rest||!R)return;const v=new THREE.Vector3();for(let i=0;i<a.count;i++){v.fromArray(rest,i*3).sub(c);const r=v.length();if(r>1e-8)v.multiplyScalar(1+.35*open*Math.max(0,1-r/R));v.add(c);a.setXYZ(i,v.x,v.y,v.z);}a.needsUpdate=true;o.geometry.computeVertexNormals();o.geometry.computeBoundingSphere();}
